 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    vals = [v for row in grid for v in row]
    bg = Counter(vals).most_common(1)[0][0]

    def bands(axis):
        n = h if axis == 0 else w
        other = w if axis == 0 else h
        full = []
        for i in range(n):
            line = [grid[i][j] for j in range(w)] if axis == 0 else [grid[j][i] for j in range(h)]
            if len(set(line)) == 1:
                full.append((i, line[0]))
        # Divider lines have one repeated color and are contiguous full lines;
        # keep only colors different from the background.
        divs = [i for i, c in full if c != bg]
        spans, start = [], 0
        for d in divs:
            if start < d:
                spans.append((start, d))
            start = d + 1
        if start < n:
            spans.append((start, n))
        return spans, {i for i, c in full if c != bg}

    rb, rdiv = bands(0)
    cb, cdiv = bands(1)
    # Choose the tile containing the most foreground cells; in a repeated
    # pattern the unfilled copies are background-only.
    candidates = []
    for ri, (ra, rz) in enumerate(rb):
        for ci, (ca, cz) in enumerate(cb):
            score = sum(grid[r][c] != bg for r in range(ra, rz) for c in range(ca, cz))
            candidates.append((score, ri, ci))
    _, sri, sci = max(candidates)
    ra, rz = rb[sri]
    ca, cz = cb[sci]
    tile = [row[ca:cz] for row in grid[ra:rz]]
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in rdiv:
        for c in range(w):
            out[r][c] = grid[r][c]
    for c in cdiv:
        for r in range(h):
            out[r][c] = grid[r][c]
    for ya, yb in rb:
        for xa, xb in cb:
            for r in range(ya, yb):
                for c in range(xa, xb):
                    out[r][c] = tile[(r - ya) % len(tile)][(c - xa) % len(tile[0])]
    return out
